import { formatDuration } from "@/lib/format";

type ThumbProps = {
  src: string | null;
  durationSeconds?: number | null;
  /** CSS aspect ratio; 16/9 by default, 2.39/1 for a lead card. */
  ratio?: string;
  className?: string;
  /** Eager-load the image (above the fold). */
  priority?: boolean;
  children?: React.ReactNode;
};

/**
 * A video thumbnail generated by the worker, or a neutral frame while there is none.
 * Decorative (alt=""): the title next to it names the video.
 */
export function Thumb({ src, durationSeconds, ratio = "16 / 9", className = "", priority = false, children }: ThumbProps) {
  return (
    <div className={`relative overflow-hidden rounded-[var(--radius-card)] bg-s2 ${className}`} style={{ aspectRatio: ratio }}>
      {src ? (
        // Plain <img>: thumbnails come from the API locally and from CloudFront (signed URL) on AWS.
        <img
          src={src}
          alt=""
          loading={priority ? "eager" : "lazy"}
          decoding="async"
          className="absolute inset-0 h-full w-full object-cover"
        />
      ) : (
        <div aria-hidden="true" className="absolute inset-0 bg-[linear-gradient(160deg,#2c2c2a,#20201f_60%,#141414)]" />
      )}
      {children}
      {typeof durationSeconds === "number" && (
        <span className="tnum absolute right-2 bottom-2 rounded bg-black/75 px-1.5 py-0.5 text-xs font-medium text-text">
          {formatDuration(durationSeconds)}
        </span>
      )}
    </div>
  );
}
